def bfs(graph, start):
    visited = {start}
    queue = [start]
    order = []
    while queue:
        node = queue.pop(0)
        order.append(node)
        for neighbor in graph.edges.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return order

def dfs(graph, start):
    visited = set()
    order = []
    dfs_visit(graph, start, visited, order)
    return order


def dfs_visit(graph, node, visited, order):
    if node in visited:
        return
    visited.add(node)
    order.append(node)
    for neighbor in graph.edges.get(node, []):
        dfs_visit(graph, neighbor, visited, order)

